function Get-UiPasswordBytes([Security.SecureString]$Password) {
    $pointer=[IntPtr]::Zero;$characters=[char[]]::new($Password.Length)
    try{$pointer=[Runtime.InteropServices.Marshal]::SecureStringToGlobalAllocUnicode($Password);[Runtime.InteropServices.Marshal]::Copy($pointer,$characters,0,$characters.Length);return ,[Text.Encoding]::UTF8.GetBytes($characters)}
    finally{[Array]::Clear($characters,0,$characters.Length);if($pointer -ne [IntPtr]::Zero){[Runtime.InteropServices.Marshal]::ZeroFreeGlobalAllocUnicode($pointer)};$Password.Dispose()}
}
function Clear-UiStoredView {
    $u=$script:reviewUi;if($u.StoredWindow){$u.StoredWindow.Close();$u.StoredWindow=$null};$u.StoredTask=$null
}
function Invoke-UiVaultLock {
    if($script:packageWindow){$script:packageWindow.Close()}
    $u=$script:reviewUi;Clear-UiStoredView;if($u.VaultContinuation -and $u.VaultContinuation.Kind -eq 'Capture'){foreach($card in $u.Cards){if($u.VaultContinuation.Request.GroupIds -contains $card.Record.GroupId){$card.IsPending=$false}}};$u.VaultContinuation=$null
    try{$u.VaultTask=$u.Engine.RequestVaultLock();$u.BackgroundOperationId=$u.VaultTask;$u.MaintenancePending=$true;Set-UiMessage 'Locking originals; protected views cleared.'}catch{Set-UiMessage $_.Exception.Message};Update-UiControls
}
function Show-UiVaultDialog($Continuation=$null) {
    $u=$script:reviewUi;if($u.MaintenancePending){Set-UiMessage 'Wait for the current task or cancel it first.';return}
    $create=-not $u.Engine.VaultExists
    $markup='<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Unlock stored originals" Width="520" Height="360" ResizeMode="NoResize" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI"><Grid Margin="20"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><TextBlock x:Name="Explanation" TextWrapping="Wrap" Margin="0,0,0,12"/><PasswordBox Grid.Row="1" x:Name="Password" Height="30" Margin="0,4" ToolTip="Originals password"/><StackPanel Grid.Row="2" x:Name="ConfirmPanel"><TextBlock Text="Confirm the new password" Margin="0,10,0,4"/><PasswordBox x:Name="Confirmation" Height="30"/></StackPanel><TextBlock Grid.Row="3" x:Name="Message" TextWrapping="Wrap" Margin="0,12,0,0"/><StackPanel Grid.Row="4" Orientation="Horizontal" HorizontalAlignment="Center"><Button x:Name="Unlock" Content="Unlock" IsDefault="True" Padding="24,7" Margin="6"/><Button x:Name="Cancel" Content="Cancel" IsCancel="True" Padding="24,7" Margin="6"/></StackPanel></Grid></Window>'
    $dialog=[Windows.Markup.XamlReader]::Parse($markup);$dialog.Owner=$u.Window;$dialog.Tag=[pscustomobject]@{Create=$create;Continuation=$Continuation}
    $dialog.FindName('Explanation').Text=if($create){'Create a password for encrypted retained originals and Evidence. Keep it safe; it cannot be recovered. Ordinary notes and thumbnails remain unencrypted.'}else{'Enter the current originals password. Newly imported HTML Evidence initially uses its saved HTML password.'}
    $dialog.FindName('ConfirmPanel').Visibility=if($create){'Visible'}else{'Collapsed'};$dialog.FindName('Unlock').Content=if($create){'Create vault'}else{'Unlock'}
    $dialog.FindName('Unlock').Add_Click({param($sender,$event)
        $window=[Windows.Window]::GetWindow($sender);$bytes=$null;$confirmation=$null
        try{$bytes=Get-UiPasswordBytes $window.FindName('Password').SecurePassword;if(-not $bytes.Length){throw 'Enter a password.'}
            if($window.Tag.Create){$confirmation=Get-UiPasswordBytes $window.FindName('Confirmation').SecurePassword;$same=$bytes.Length -eq $confirmation.Length;for($i=0;$i -lt [Math]::Min($bytes.Length,$confirmation.Length);$i++){if($bytes[$i] -ne $confirmation[$i]){$same=$false}};if(-not $same){throw 'The passwords do not match.'}}
            $u=$script:reviewUi;$u.VaultContinuation=$window.Tag.Continuation;$u.VaultTask=$u.Engine.RequestVaultUnlock($bytes,[bool]$window.Tag.Create);$bytes=$null;$u.BackgroundOperationId=$u.VaultTask;$u.MaintenancePending=$true;Set-UiMessage 'Checking the originals password...';$window.DialogResult=$true
        }catch{$window.FindName('Message').Text=$_.Exception.Message}finally{if($bytes){[Array]::Clear($bytes,0,$bytes.Length)};if($confirmation){[Array]::Clear($confirmation,0,$confirmation.Length)};$window.FindName('Password').Clear();$window.FindName('Confirmation').Clear()}
    })
    $u.VaultDialog=$dialog;try{$dialog.ShowDialog() | Out-Null}finally{$u.VaultDialog=$null};Update-UiControls
}
function Start-UiOriginalRetention([MediaReviewer.ReviewRequest]$Request,[string]$Bucket) {
    $u=$script:reviewUi;if($u.MaintenancePending){Set-UiMessage 'Wait for the current task or cancel it first.';return}
    try{if($Bucket -eq 'EVIDENCE'){[MediaReviewer.ReviewerEngine]::ValidateEvidenceReclassify($Request)}else{[MediaReviewer.ReviewerEngine]::ValidateOriginalRetention($Request)}}catch{foreach($card in $u.Cards){if($Request.GroupIds -contains $card.Record.GroupId){$card.IsPending=$false}};Set-UiMessage ('Retention failed; selection retained. Use at most 128 reviewer characters and 16,384 note characters. '+$_.Exception.Message);Update-UiControls;return}
    if(-not $Request.ExpectedRevisions){$Request.ExpectedRevisions=[Collections.Generic.Dictionary[long,long]]::new();foreach($card in $u.Cards){if($Request.GroupIds -contains $card.Record.GroupId){$Request.ExpectedRevisions[$card.Record.GroupId]=$card.Record.ReviewRevision}}}
    $retry=$u.RetentionRetry;if($retry -and $retry.Database -eq $u.Engine.DatabasePath){$old=$retry.Request;if($old.Status -ceq $Request.Status -and $old.Reviewer -ceq $Request.Reviewer -and $old.Notes -ceq $Request.Notes -and (($old.GroupIds | Sort-Object) -join ',') -ceq (($Request.GroupIds | Sort-Object) -join ',')){$Request.OperationId=$old.OperationId}}
    if(-not $u.Engine.VaultUnlocked){foreach($card in $u.Cards){if($Request.GroupIds -contains $card.Record.GroupId){$card.IsPending=$true}};Show-UiVaultDialog ([pscustomobject]@{Kind='Capture';Request=$Request;Bucket=$Bucket});if(-not $u.MaintenancePending){foreach($card in $u.Cards){if($Request.GroupIds -contains $card.Record.GroupId){$card.IsPending=$false}}};return}
    try{$id=if($Bucket -eq 'EVIDENCE'){$u.Engine.RequestEvidenceReclassify($Request)}else{$u.Engine.RequestOriginalRetention($Request)};$u.Pending[$id]=[pscustomobject]@{Ids=$Request.GroupIds;Bucket=$Bucket;Target=$Request.Status;OperationId=$Request.OperationId;Capture=$true;Request=$Request};$u.MaintenancePending=$true;$u.BackgroundOperationId=$id;foreach($card in $u.Cards){if($Request.GroupIds -contains $card.Record.GroupId){$card.IsPending=$true}};Set-UiMessage $(if($Bucket -eq 'EVIDENCE'){'Authenticating stored originals; Evidence reviews change after commit.'}else{'Retaining verified encrypted originals; the review changes after commit.'})}catch{foreach($card in $u.Cards){if($Request.GroupIds -contains $card.Record.GroupId){$card.IsPending=$false}};Set-UiMessage ('Retention failed; selection retained: '+$_.Exception.Message)};Update-UiControls
}
function Invoke-UiEvidenceCapture {
    $u=$script:reviewUi;$cards=@($u.Cards | Where-Object {$_.IsSelected -and -not $_.IsPending});if(-not $cards.Count){return}
    $r=[MediaReviewer.ReviewRequest]::new();$r.OperationId=[Guid]::NewGuid().ToString('N');$r.GroupIds=[long[]]@($cards | ForEach-Object {$_.Record.GroupId});$r.Status='EVIDENCE';$r.Reviewer=$u.Controls.ReviewerBox.Text;$r.Notes=$u.Controls.NotesBox.Text;Start-UiOriginalRetention $r $u.Bucket
}
function Invoke-UiStoredInspect($Card=$null) {
    $u=$script:reviewUi;if(-not $Card){$selected=@($u.Cards | Where-Object {$_.IsSelected});if($selected.Count -ne 1){return};$Card=$selected[0]}
    if($u.MaintenancePending){Set-UiMessage 'Wait for the current task or cancel it first.';return}
    if(-not $u.Engine.VaultUnlocked){Show-UiVaultDialog ([pscustomobject]@{Kind='Inspect';Card=$Card});return}
    Clear-UiStoredView
    try{$id=$u.Engine.RequestEvidenceInspect($Card.Record.GroupId);$u.StoredTask=[pscustomobject]@{Id=$id;Group=$Card.Record.GroupId;View=$u.View.Current;Selection=$u.SelectionGeneration;Epoch=$u.Engine.VaultGeneration};$u.BackgroundOperationId=$id;$u.MaintenancePending=$true;Set-UiMessage 'Authenticating the retained original...'}catch{Set-UiMessage $_.Exception.Message};Update-UiControls
}
function Show-UiStoredOriginal([MediaReviewer.EvidenceInspection]$Original) {
    $u=$script:reviewUi;Clear-UiStoredView
    $markup='<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Verified stored original" Width="850" Height="650" MinWidth="500" MinHeight="400" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI"><Grid Margin="16"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><TextBox x:Name="Details" IsReadOnly="True" TextWrapping="Wrap" MaxHeight="200" VerticalScrollBarVisibility="Auto" Margin="0,0,0,10"/><Border Grid.Row="1" Background="#EAF0F5"><Image x:Name="Picture" Stretch="Uniform"/></Border><Button Grid.Row="2" x:Name="Close" Content="Close" IsCancel="True" HorizontalAlignment="Center" Padding="24,7" Margin="0,12,0,0"/></Grid></Window>'
    $window=[Windows.Markup.XamlReader]::Parse($markup);$window.Owner=$u.Window;$window.Tag=$Original;$u.StoredWindow=$window
    $details='';$length=[Math]::Min(32768,$Original.Metadata.Length);$text=[Text.Encoding]::UTF8.GetString($Original.Metadata,0,$length)
    if($length -lt $Original.Metadata.Length){$details='Capture details exceed the display limit; their encrypted original is preserved.'}else{try{$meta=$text | ConvertFrom-Json;$details=@($meta.name,$meta.path,$meta.capturedAt,$meta.notes,$meta.displayNotice) -join "`r`n"}catch{$details='Authenticated capture details are preserved in the database.'}}
    $window.FindName('Details').Text="Verified original: $($Original.Size) bytes`r`nSHA-256: $($Original.Hash)`r`n$details`r`nThe image below is the saved thumbnail. Use Export original for full resolution."
    if($Original.PreviewImage){$window.FindName('Picture').Source=$Original.PreviewImage}elseif($Original.PreviewError){Set-UiMessage $Original.PreviewError}
    $window.FindName('Close').Add_Click({param($sender,$event) [Windows.Window]::GetWindow($sender).Close()})
    $window.Add_Closed({param($sender,$event) $sender.FindName('Picture').Source=$null;$sender.FindName('Details').Clear();if($sender.Tag){$sender.Tag.Dispose();$sender.Tag=$null};if($script:reviewUi.StoredWindow -eq $sender){$script:reviewUi.StoredWindow=$null}});$window.Show()
}
function Invoke-UiOriginalExport {
    $u=$script:reviewUi;$cards=@($u.Cards | Where-Object {$_.IsSelected});if($cards.Count -ne 1 -or $u.MaintenancePending){return}
    if(-not $u.Engine.VaultUnlocked){Show-UiVaultDialog ([pscustomobject]@{Kind='Export'});return}
    $picker=[Microsoft.Win32.SaveFileDialog]::new();$picker.Title='Export decrypted original to a new file';$picker.FileName=('Original-'+$cards[0].Record.GroupId+'.bin');$picker.Filter='Original file (*.*)|*.*'
    if($picker.ShowDialog($u.Window)){try{$operation=[Guid]::NewGuid().ToString('N');if($u.ExportRetry -and $u.ExportRetry.Database -eq $u.Engine.DatabasePath -and $u.ExportRetry.Group -eq $cards[0].Record.GroupId -and $u.ExportRetry.Path -ceq $picker.FileName){$operation=$u.ExportRetry.Operation};$u.ExportRetry=[pscustomobject]@{Database=$u.Engine.DatabasePath;Group=$cards[0].Record.GroupId;Path=$picker.FileName;Operation=$operation};$id=$u.Engine.RequestEvidenceOriginalExport($cards[0].Record.GroupId,$picker.FileName,$operation);$u.MaintenancePending=$true;$u.BackgroundOperationId=$id;Set-UiMessage 'Verifying the original before writing the explicitly chosen output...'}catch{Set-UiMessage $_.Exception.Message}};Update-UiControls
}
function Apply-UiEvidenceResult($Result) {
    $u=$script:reviewUi
    if($Result.Kind -in @('VaultUnlock','VaultLock','VaultPasswordChange')){
        if($Result.RequestId -ne $u.VaultTask){return $true};$u.VaultTask='';$u.MaintenancePending=$false;$u.BackgroundOperationId='';$continuation=$u.VaultContinuation;$u.VaultContinuation=$null;Set-UiMessage $(if($Result.Success){$Result.Value}else{'Originals remain locked: '+$Result.Error})
        if($Result.Kind -eq 'VaultPasswordChange' -and $Result.Success){$u.PasswordRetry=$null}
        if(-not $Result.Success -and $continuation -and $continuation.Kind -eq 'Capture'){foreach($card in $u.Cards){if($continuation.Request.GroupIds -contains $card.Record.GroupId){$card.IsPending=$false}}}
        if($Result.Success -and $u.Engine.VaultUnlocked -and $continuation){switch($continuation.Kind){'Capture'{Start-UiOriginalRetention $continuation.Request $continuation.Bucket};'Inspect'{Invoke-UiStoredInspect $continuation.Card};'Export'{Invoke-UiOriginalExport};'Package'{Invoke-UiPackageExport}}};Update-UiControls;return $true
    }
    if($Result.Kind -eq 'EvidenceInspect'){
        $task=$u.StoredTask;if(-not $task -or $task.Id -ne $Result.RequestId){if($Result.Evidence){$Result.Evidence.Dispose()};return $true};$u.StoredTask=$null;if($Result.RequestId -eq $u.BackgroundOperationId){$u.MaintenancePending=$false;$u.BackgroundOperationId=''}
        if($Result.Success -and $Result.Evidence -and $task -and $task.Id -eq $Result.RequestId -and $task.View -eq $u.View.Current -and $task.Selection -eq $u.SelectionGeneration -and $u.Engine.VaultUnlocked -and $Result.Evidence.Epoch -eq $u.Engine.VaultGeneration){Show-UiStoredOriginal $Result.Evidence;Set-UiMessage 'Stored original authenticated and verified.'}else{if($Result.Evidence){$Result.Evidence.Dispose()};Set-UiMessage $(if($Result.Success){'Protected result discarded because the selection changed.'}else{'Original inspection failed: '+$Result.Error})};Update-UiControls;return $true
    }
    if($Result.Kind -in @('OriginalExport','EvidenceLimit','OriginalCleanup')){if($Result.RequestId -eq $u.BackgroundOperationId){$u.MaintenancePending=$false;$u.BackgroundOperationId=''};if($Result.Kind -eq 'OriginalExport' -and $Result.Success){$u.ExportRetry=$null};Set-UiMessage $(if($Result.Success){$Result.Value}else{$Result.Error});Update-UiControls;return $true};return $false
}
function Add-UiEvidenceControls($Window) {
    $u=$script:reviewUi;foreach($name in @('CaptureEvidenceButton','VaultButton','StoredOriginalButton','ExportOriginalButton')){$u.Controls[$name]=$Window.FindName($name)}
    foreach($entry in @{StoredWindow=$null;StoredTask=$null;VaultTask='';VaultContinuation=$null;VaultDialog=$null;RetentionRetry=$null;ExportRetry=$null;PasswordRetry=$null}.GetEnumerator()){$u | Add-Member -NotePropertyName $entry.Key -NotePropertyValue $entry.Value -Force}
    $u.Controls.CaptureEvidenceButton.Add_Click({Invoke-UiEvidenceCapture});$u.Controls.StoredOriginalButton.Add_Click({Invoke-UiStoredInspect});$u.Controls.ExportOriginalButton.Add_Click({Invoke-UiOriginalExport});$u.Controls.VaultButton.Add_Click({if($script:reviewUi.Engine.VaultUnlocked){Invoke-UiVaultLock}else{Show-UiVaultDialog}})
    foreach($gb in @(2.5,5)){$item=[Windows.Controls.MenuItem]::new();$item.Header="Retained-original guardrail: $gb GB";$item.Tag=$gb;$item.Add_Click({param($sender,$event) try{$u=$script:reviewUi;$u.BackgroundOperationId=$u.Engine.RequestEvidenceLimit([double]$sender.Tag);$u.MaintenancePending=$true;Set-UiMessage 'Saving the retained-original guardrail...';Update-UiControls}catch{Set-UiMessage $_.Exception.Message}});[void]$u.Controls.MaintenanceButton.ContextMenu.Items.Add($item)}
    $cleanup=[Windows.Controls.MenuItem]::new();$cleanup.Header='Discard unfinished original captures';$cleanup.Add_Click({try{$u=$script:reviewUi;$u.BackgroundOperationId=$u.Engine.RequestOriginalCleanup();$u.MaintenancePending=$true;Set-UiMessage 'Discarding hidden incomplete captures in bounded batches...';Update-UiControls}catch{Set-UiMessage $_.Exception.Message}});[void]$u.Controls.MaintenanceButton.ContextMenu.Items.Add($cleanup)
    $change=[Windows.Controls.MenuItem]::new();$change.Header='Change originals password...';$change.Add_Click({Show-UiPasswordChangeDialog});[void]$u.Controls.MaintenanceButton.ContextMenu.Items.Add($change)
}
function Show-UiPasswordChangeDialog {
    $u=$script:reviewUi;if($u.MaintenancePending -or -not $u.Engine.VaultExists){Set-UiMessage 'Wait for the current task and create an originals vault before changing its password.';return}
    $markup='<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Change originals password" Width="520" Height="470" ResizeMode="NoResize" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI"><Grid Margin="20"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><TextBlock Text="Enter the current password and choose a new one. Saved originals stay intact. Earlier database copies keep their old password. Keep the new password safe; it cannot be recovered." TextWrapping="Wrap" Margin="0,0,0,12"/><StackPanel Grid.Row="1"><TextBlock Text="Current password"/><PasswordBox x:Name="Password" Height="30" Margin="0,4,0,10"/></StackPanel><StackPanel Grid.Row="2"><TextBlock Text="New password"/><PasswordBox x:Name="NewPassword" Height="30" Margin="0,4,0,10"/></StackPanel><StackPanel Grid.Row="3"><TextBlock Text="Confirm new password"/><PasswordBox x:Name="Confirmation" Height="30" Margin="0,4"/></StackPanel><TextBlock Grid.Row="4" x:Name="Message" TextWrapping="Wrap" Margin="0,10"/><StackPanel Grid.Row="5" Orientation="Horizontal" HorizontalAlignment="Center"><Button x:Name="Unlock" Content="Change password" IsDefault="True" Padding="18,7" Margin="6"/><Button Content="Cancel" IsCancel="True" Padding="24,7" Margin="6"/></StackPanel></Grid></Window>'
    $dialog=[Windows.Markup.XamlReader]::Parse($markup);$dialog.Owner=$u.Window
    $dialog.FindName('Unlock').Add_Click({param($sender,$event)
        $window=[Windows.Window]::GetWindow($sender);$current=$null;$next=$null;$confirmation=$null
        try{$current=Get-UiPasswordBytes $window.FindName('Password').SecurePassword;$next=Get-UiPasswordBytes $window.FindName('NewPassword').SecurePassword;$confirmation=Get-UiPasswordBytes $window.FindName('Confirmation').SecurePassword
            if(-not $current.Length -or -not $next.Length){throw 'Enter both the current and new password.'};$same=$next.Length -eq $confirmation.Length;for($i=0;$i -lt [Math]::Min($next.Length,$confirmation.Length);$i++){if($next[$i] -ne $confirmation[$i]){$same=$false}};if(-not $same){throw 'The new passwords do not match.'}
            $u=$script:reviewUi;$operation=[Guid]::NewGuid().ToString('N');if($u.PasswordRetry -and $u.PasswordRetry.Database -eq $u.Engine.DatabasePath){$operation=$u.PasswordRetry.Operation};Clear-UiStoredView;$u.VaultContinuation=$null;$u.PasswordRetry=[pscustomobject]@{Database=$u.Engine.DatabasePath;Operation=$operation};$u.VaultTask=$u.Engine.RequestVaultPasswordChange($current,$next,$operation);$current=$null;$next=$null;$u.BackgroundOperationId=$u.VaultTask;$u.MaintenancePending=$true;Set-UiMessage 'Checking the current password and updating the encrypted content-key record...';$window.DialogResult=$true
        }catch{$window.FindName('Message').Text=$_.Exception.Message}finally{foreach($bytes in @($current,$next,$confirmation)){if($bytes){[Array]::Clear($bytes,0,$bytes.Length)}};foreach($name in @('Password','NewPassword','Confirmation')){$window.FindName($name).Clear()}}
    })
    $u.VaultDialog=$dialog;try{$dialog.ShowDialog() | Out-Null}finally{$u.VaultDialog=$null};Update-UiControls
}

function Get-UiInspectorDpi($Window) {
    $presentation=[Windows.PresentationSource]::FromVisual($Window)
    if($presentation -and $presentation.CompositionTarget){return $presentation.CompositionTarget.TransformToDevice}
    return [Windows.Media.Matrix]::Identity
}
function Update-UiInspectorGeometry([switch]$Center) {
    $u=$script:reviewUi;$window=$u.Inspector;if(-not $window -or -not $window.Tag){return};$s=$window.Tag;$view=$window.FindName('Viewport');$picture=$window.FindName('Picture');$dpi=Get-UiInspectorDpi $window
    $width=[Math]::Max(1,$view.ActualWidth-2)*$dpi.M11;$height=[Math]::Max(1,$view.ActualHeight-2)*$dpi.M22
    $sourceWidth=$s.SourceWidth;$sourceHeight=$s.SourceHeight;if($sourceWidth -le 0 -and $s.Image){$sourceWidth=$s.Image.PixelWidth;$sourceHeight=$s.Image.PixelHeight}
    if($sourceWidth -gt 0){
        $oldWidth=[Math]::Max(1,$view.ExtentWidth);$oldHeight=[Math]::Max(1,$view.ExtentHeight);$cx=($view.HorizontalOffset+$view.ViewportWidth/2)/$oldWidth;$cy=($view.VerticalOffset+$view.ViewportHeight/2)/$oldHeight
        $s.Plan=[MediaReviewer.InspectionPlan]::Create($sourceWidth,$sourceHeight,$width,$height,$s.Mode,$s.Zoom);$picture.Width=$s.Plan.DisplayWidth/$dpi.M11;$picture.Height=$s.Plan.DisplayHeight/$dpi.M22;$picture.Source=$s.Image;$view.UpdateLayout()
        if($s.Mode -eq 'Fit'){$view.ScrollToHorizontalOffset(0);$view.ScrollToVerticalOffset(0)}elseif($Center -or $s.Mode -eq 'Fill'){$view.ScrollToHorizontalOffset([Math]::Max(0,($view.ExtentWidth-$view.ViewportWidth)/2));$view.ScrollToVerticalOffset([Math]::Max(0,($view.ExtentHeight-$view.ViewportHeight)/2))}else{$view.ScrollToHorizontalOffset([Math]::Max(0,$cx*$view.ExtentWidth-$view.ViewportWidth/2));$view.ScrollToVerticalOffset([Math]::Max(0,$cy*$view.ExtentHeight-$view.ViewportHeight/2))}
        $kind=if($s.SourceLoaded){'Source'}else{'Saved preview'};$details=if($s.Image){"$($s.Image.PixelWidth) × $($s.Image.PixelHeight) preview"}else{'Loading'};$limited=if($s.Plan.Limited -or ($s.SourceLoaded -and $s.Image -and [Math]::Max($s.Image.PixelWidth,$s.Image.PixelHeight)+1 -lt [Math]::Min([Math]::Max($s.SourceWidth,$s.SourceHeight),[Math]::Max($s.Plan.DisplayWidth,$s.Plan.DisplayHeight)))){' · sampled for preview limits'}else{''};$window.FindName('ZoomLabel').Text=('{0:0.##}% · {1} {2} × {3} · {4}{5}' -f ($s.Plan.Scale*100),$kind,$sourceWidth,$sourceHeight,$details,$limited)
    }
    foreach($name in @('ZoomInButton','ZoomOutButton','ActualButton')){$window.FindName($name).IsEnabled=$s.SourceLoaded -or $s.Failed};$window.FindName('ActualButton').Content=if($s.Failed){'100% preview'}else{'100%'}
}
function Schedule-UiInspectorPreview {
    $u=$script:reviewUi;if(-not $u.Inspector -or -not $u.Inspector.Tag){return};$s=$u.Inspector.Tag
    $s.Timer.Stop();[void]$u.InspectView.Advance();$u.Loader.CancelInspect($u.InspectView.Current);$s.Generation=$u.InspectView.Current;$s.Loading=$false;Update-UiInspectorGeometry
    if($s.Failed){return};$s.Loading=$true;$u.Inspector.FindName('Status').Text='Preparing source preview…';$s.Timer.Start()
}
function Request-UiInspectorPreview {
    $u=$script:reviewUi;$window=$u.Inspector;if(-not $window -or -not $window.Tag){return};$s=$window.Tag;$s.Timer.Stop();if($s.Failed){$s.Loading=$false;return};Update-UiInspectorGeometry
    if($s.SourceLoaded){$side=$s.Plan.DecodeSide}else{$view=$window.FindName('Viewport');$dpi=Get-UiInspectorDpi $window;$side=[int][Math]::Max(1,[Math]::Min([MediaReviewer.InspectionPlan]::MaxSide,[Math]::Ceiling([Math]::Max($view.ActualWidth*$dpi.M11,$view.ActualHeight*$dpi.M22))))}
    if($s.SourceLoaded -and $side -le $s.LoadedSide){$s.Loading=$false;$window.FindName('Status').Text='Source preview ready. Drag to pan when zoomed; Ctrl+wheel changes zoom.';return}
    $s.RequestedSide=$side;$s.Loading=$true;$window.FindName('Status').Text='Loading source preview…';try{if(-not $u.Loader.QueueInspect($s.Row,$s.Generation,$side)){$s.Loading=$false;$window.FindName('Status').Text='The inspector is closing. The cached preview remains available.'}}catch{$s.Loading=$false;$window.FindName('Status').Text=$_.Exception.Message}
}
function Set-UiInspectorMode([string]$Mode,[double]$Zoom=1) {
    $u=$script:reviewUi;if(-not $u.Inspector -or -not $u.Inspector.Tag){return};$s=$u.Inspector.Tag;$s.Mode=$Mode;$s.Zoom=$Zoom;Update-UiInspectorGeometry -Center;Schedule-UiInspectorPreview
}
function Step-UiInspectorZoom([double]$Factor) {
    $u=$script:reviewUi;if(-not $u.Inspector -or -not $u.Inspector.Tag -or -not $u.Inspector.Tag.Plan){return};$s=$u.Inspector.Tag;if(-not $s.SourceLoaded -and -not $s.Failed){return};$s.Mode='Zoom';$s.Zoom=$s.Plan.Scale*$Factor;Update-UiInspectorGeometry;Schedule-UiInspectorPreview
}
function Apply-UiInspectorImage($Image) {
    $u=$script:reviewUi;$window=$u.Inspector;if(-not $window -or -not $window.Tag){return $false};$s=$window.Tag
    if(-not $u.InspectView.Accept($Image.Generation) -or $Image.GroupId -ne $s.Row.GroupId -or $Image.ContentId -ne $s.Row.ContentId){return $false}
    $s.Loading=$false
    if($Image.Image){$s.Image=$Image.Image;$s.SourceWidth=$Image.SourceWidth;$s.SourceHeight=$Image.SourceHeight;$s.LoadedSide=$Image.RequestedSide;$s.SourceLoaded=$true;$s.Failed=$false;$window.FindName('Status').Text='Source preview ready. Drag to pan when zoomed; Ctrl+wheel changes zoom.'}
    else{$s.Failed=$true;$window.FindName('Status').Text='Source unavailable; saved preview retained. '+$Image.Error}
    Update-UiInspectorGeometry;return $true
}
function Update-UiInspectorThumbnail($Card) {
    $u=$script:reviewUi;if($u.Inspector -and $u.Inspector.Tag){$s=$u.Inspector.Tag;if(-not $s.SourceLoaded -and $s.Row.GroupId -eq $Card.Record.GroupId -and $s.Row.ContentId -eq $Card.Record.ContentId){$s.Image=$Card.Image;Update-UiInspectorGeometry}}
}
function Show-UiInspector($Card) {
    if($Card.Record.Status -eq 'EVIDENCE' -or ($Card.Record.OriginalRetained -and [string]::IsNullOrEmpty($Card.Record.RelativePath))){if($script:reviewUi.Inspector){$script:reviewUi.Inspector.Close()};Invoke-UiStoredInspect $Card;return}
    $u=$script:reviewUi
    if($script:reviewUi.SourceRefreshRequired){Set-UiMessage 'Refreshing source locations; cached gallery images remain available.';return}
    if(-not $u.Inspector){
        $markup=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Inspect media" Width="900" Height="650" MinWidth="500" MinHeight="400" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI">
  <Grid Margin="16"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="64"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <StackPanel><TextBlock x:Name="Name" FontSize="18" TextTrimming="CharacterEllipsis"/><TextBlock x:Name="Path" TextTrimming="CharacterEllipsis" Margin="0,4"/></StackPanel>
    <WrapPanel Grid.Row="1" Margin="0,6,0,10"><Button x:Name="PreviousItem" Content="Previous item" Padding="10,6" Margin="0,0,6,4"/><Button x:Name="NextItem" Content="Next item" Padding="10,6" Margin="0,0,6,4"/><Button x:Name="Details" Content="Details / notes" Padding="10,6" Margin="0,0,8,4"/><TextBlock x:Name="Position" VerticalAlignment="Center" Margin="0,0,10,4"/><Button x:Name="FitButton" Content="Fit" Padding="14,6" Margin="0,0,6,4" ToolTip="Show the whole image"/><Button x:Name="FillButton" Content="Fill" Padding="14,6" Margin="0,0,6,4" ToolTip="Fill the viewport and crop around the center"/><Button x:Name="ZoomOutButton" Content="−" Padding="14,6" Margin="0,0,6,4" ToolTip="Zoom out"/><Button x:Name="ZoomInButton" Content="+" Padding="14,6" Margin="0,0,6,4" ToolTip="Zoom in"/><Button x:Name="ActualButton" Content="100%" Padding="14,6" Margin="0,0,10,4" ToolTip="Display at source pixel scale; preview detail remains bounded"/><TextBlock x:Name="ZoomLabel" VerticalAlignment="Center" TextWrapping="Wrap"/></WrapPanel>
    <Border Grid.Row="2" Background="#EAF0F5" ClipToBounds="True"><ScrollViewer x:Name="Viewport" HorizontalScrollBarVisibility="Auto" VerticalScrollBarVisibility="Auto" CanContentScroll="False" Focusable="True"><Image x:Name="Picture" Stretch="Uniform" HorizontalAlignment="Center" VerticalAlignment="Center"/></ScrollViewer></Border>
    <TextBlock Grid.Row="3" x:Name="Status" TextWrapping="Wrap" Margin="0,8,0,0"/>
    <Button Grid.Row="4" x:Name="Close" Content="Close" HorizontalAlignment="Center" Padding="22,6" Margin="0,8,0,0" IsCancel="True"/>
  </Grid>
</Window>
'@
        $u.Inspector=[Windows.Markup.XamlReader]::Parse($markup);$u.Inspector.Owner=$u.Window
        $u.Inspector.FindName('Close').Add_Click({$script:reviewUi.Inspector.Close()})
        $u.Inspector.FindName('FitButton').Add_Click({Set-UiInspectorMode 'Fit'});$u.Inspector.FindName('FillButton').Add_Click({Set-UiInspectorMode 'Fill'});$u.Inspector.FindName('ActualButton').Add_Click({Set-UiInspectorMode 'Zoom' 1});$u.Inspector.FindName('ZoomInButton').Add_Click({Step-UiInspectorZoom 1.25});$u.Inspector.FindName('ZoomOutButton').Add_Click({Step-UiInspectorZoom .8})
        $u.Inspector.FindName('PreviousItem').Add_Click({$card=Get-UiPageNeighbor $script:reviewUi.InspectGroup -1;if($card){Show-UiInspector $card}});$u.Inspector.FindName('NextItem').Add_Click({$card=Get-UiPageNeighbor $script:reviewUi.InspectGroup 1;if($card){Show-UiInspector $card}});$u.Inspector.FindName('Details').Add_Click({$card=Get-UiPageNeighbor $script:reviewUi.InspectGroup 0;if($card){Show-UiDetails $card}})
        $u.Inspector.FindName('Viewport').Add_SizeChanged({Schedule-UiInspectorPreview})
        $u.Inspector.FindName('Viewport').Add_PreviewMouseWheel({param($sender,$event) if(([Windows.Input.Keyboard]::Modifiers -band [Windows.Input.ModifierKeys]::Control) -ne 0){Step-UiInspectorZoom $(if($event.Delta -gt 0){1.25}else{.8});$event.Handled=$true}})
        $u.Inspector.FindName('Picture').Add_MouseLeftButtonDown({param($sender,$event) $w=[Windows.Window]::GetWindow($sender);$s=$w.Tag;$view=$w.FindName('Viewport');$s.Pan=$event.GetPosition($view);$s.PanX=$view.HorizontalOffset;$s.PanY=$view.VerticalOffset;[void]$sender.CaptureMouse();$event.Handled=$true})
        $u.Inspector.FindName('Picture').Add_MouseMove({param($sender,$event) $w=[Windows.Window]::GetWindow($sender);$s=$w.Tag;if($s -and $s.Pan -and $event.LeftButton -eq [Windows.Input.MouseButtonState]::Pressed){$view=$w.FindName('Viewport');$position=$event.GetPosition($view);$view.ScrollToHorizontalOffset($s.PanX+$s.Pan.X-$position.X);$view.ScrollToVerticalOffset($s.PanY+$s.Pan.Y-$position.Y);$event.Handled=$true}})
        $u.Inspector.FindName('Picture').Add_MouseLeftButtonUp({param($sender,$event) $w=[Windows.Window]::GetWindow($sender);if($w.Tag){$w.Tag.Pan=$null};$sender.ReleaseMouseCapture();$event.Handled=$true})
        $u.Inspector.Add_Closed({param($sender,$event) if($sender.Tag){$sender.Tag.Timer.Stop();$sender.Tag.Image=$null;$sender.Tag.Row=$null;$sender.Tag=$null};$sender.FindName('Picture').Source=$null;$sender.FindName('Name').Text='';$sender.FindName('Path').Text='';$u=$script:reviewUi;if($u.Inspector -eq $sender){[void]$u.InspectView.Advance();$u.Loader.CancelInspect($u.InspectView.Current);$u.Inspector=$null}})
    }
    $window=$u.Inspector;if($window.Tag){$window.Tag.Timer.Stop();$window.Tag.Image=$null};$window.FindName('Picture').Source=$null;[void]$u.InspectView.Advance();$u.Loader.CancelInspect($u.InspectView.Current);$u.InspectGroup=$Card.Record.GroupId
    $timer=[Windows.Threading.DispatcherTimer]::new();$timer.Interval=[TimeSpan]::FromMilliseconds(180);$timer.Add_Tick({Request-UiInspectorPreview})
    $window.Tag=[pscustomobject]@{Row=$Card.Record;Image=$Card.Image;SourceWidth=0;SourceHeight=0;SourceLoaded=$false;Failed=$false;Loading=$true;Mode='Fit';Zoom=1.0;Plan=$null;LoadedSide=0;RequestedSide=0;Generation=$u.InspectView.Current;Timer=$timer;Pan=$null;PanX=0.0;PanY=0.0}
    Update-UiItemNavigation $window $u.InspectGroup 'PreviousItem' 'NextItem' 'Position'
    $window.FindName('Name').Text=$Card.Name;$window.FindName('Path').Text=$Card.FullPath;$window.FindName('Path').ToolTip=$Card.FullPath;$window.FindName('ZoomLabel').Text='Loading source dimensions…';$window.FindName('Status').Text='Loading source preview…';$window.Show();$window.Activate() | Out-Null;Update-UiInspectorGeometry -Center;Schedule-UiInspectorPreview
}

function Update-UiDetailsSummary {
    $w=$script:reviewUi.DetailsWindow;$d=$w.Tag.Data;if(-not $d){return}
        $match=if($d.Algorithm -eq 'sha256'){'Verified full-file identity'}else{'Quick candidate identity; equality is not proof of identical files'}
        $w.FindName('Summary').Text=("Group {0} | Publication {1} | {2} | {3:n0} bytes`nRoot: {4}`n{5}`n{6} v{7}: {8}`nSampling: {9}`nPreview: {10} {11}`nLast saved review: {12}" -f $d.GroupId,$d.Sequence,$d.Status,$d.Size,$d.RootPath,$match,$d.Algorithm,$d.AlgorithmVersion,$d.Digest,$d.Sampling,$d.PreviewState,$d.PreviewError,$d.ReviewedAt)
}
function Refresh-UiDetailsSource {
    $u=$script:reviewUi;$w=$u.DetailsWindow;if(-not $w -or -not $w.Tag){return};$s=$w.Tag
    if(-not $s.Data -and -not $s.Dirty -and -not $s.Saving){Request-UiDetailsMetadata $s.GroupId;return}
    $s.Generation=$u.DetailsGeneration.Advance();$s.MetadataRequest='';$s.SourceRequest='';$s.LocationRequest='';$s.LocationPending=$false;$s.HasMore=$false
    $w.FindName('Summary').Text='Refreshing connected source...';$w.FindName('Locations').ItemsSource=$null;$w.FindName('LocationLabel').Text='Refreshing recorded locations...';Update-UiDetailsControls
    try{$s.SourceRequest=$u.Engine.RequestInspector($s.GroupId,$s.Generation)}catch{$w.FindName('Summary').Text='Connected source summary unavailable: '+$_.Exception.Message}
}
function Get-UiPageNeighbor([long]$Group,[int]$Offset) {
    $cards=$script:reviewUi.Cards;for($i=0;$i -lt $cards.Count;$i++){if($cards[$i].Record.GroupId -eq $Group){$index=$i+$Offset;if($index -ge 0 -and $index -lt $cards.Count){return $cards[$index]};return $null}};return $null
}
function Update-UiItemNavigation($Window,[long]$Group,[string]$Previous,[string]$Next,[string]$Label,[bool]$Blocked=$false) {
    $cards=$script:reviewUi.Cards;$index=-1;for($i=0;$i -lt $cards.Count;$i++){if($cards[$i].Record.GroupId -eq $Group){$index=$i;break}}
    $Window.FindName($Previous).IsEnabled=-not $Blocked -and $index -gt 0;$Window.FindName($Next).IsEnabled=-not $Blocked -and $index -ge 0 -and $index -lt $cards.Count-1
    $Window.FindName($Label).Text=if($index -ge 0){'{0} of {1} on this page' -f ($index+1),$cards.Count}else{'Outside the current page'}
}
function Update-UiDetailsControls {
    $u=$script:reviewUi;$w=$u.DetailsWindow;if(-not $w -or -not $w.Tag){return};$s=$w.Tag;$editable=$s.Data -and -not $s.Data.TextReadOnly -and -not $s.Saving
    $w.FindName('Reviewer').IsReadOnly=-not $editable;$w.FindName('Notes').IsReadOnly=-not $editable;$w.FindName('Save').IsEnabled=$editable -and $s.Dirty -and -not $u.Engine.ReportActive;$w.FindName('Reload').IsEnabled=-not $s.Saving
    $w.FindName('MoreLocations').IsEnabled=-not $s.LocationPending -and $s.HasMore -and [bool]$s.Data
    Update-UiItemNavigation $w $s.GroupId 'Previous' 'Next' 'Position' ($s.Saving -or $s.Dirty)
}
function Request-UiDetailsLocations([switch]$Restart) {
    $u=$script:reviewUi;$w=$u.DetailsWindow;if(-not $w -or -not $w.Tag.Data){return};$s=$w.Tag;if($Restart){$s.Cursor='';$s.Shown=0}
    $s.LocationPending=$true;$s.HasMore=$false;$w.FindName('LocationLabel').Text='Loading recorded locations...';Update-UiDetailsControls
    try{$s.LocationRequest=$u.Engine.RequestLocations($s.GroupId,$s.Cursor,100)}catch{$s.LocationPending=$false;$w.FindName('LocationLabel').Text='Locations unavailable: '+$_.Exception.Message;Update-UiDetailsControls}
}
function Request-UiDetailsMetadata([long]$Group) {
    $u=$script:reviewUi;$w=$u.DetailsWindow;$s=$w.Tag;$s.Loading=$true;$s.GroupId=$Group;$s.Data=$null;$s.Dirty=$false;$s.MetadataRequest='';$s.SourceRequest='';$s.LocationRequest='';$s.LocationPending=$false;$s.HasMore=$false;$s.OperationId='';$s.LastRequest=$null
    $s.Generation=$u.DetailsGeneration.Advance();$w.FindName('Summary').Text='Loading item details...';$w.FindName('Reviewer').Clear();$w.FindName('Notes').Clear();$w.FindName('Locations').ItemsSource=$null;$w.FindName('LocationLabel').Text='';$w.FindName('Status').Text='Loading saved metadata...';$s.Loading=$false;Update-UiDetailsControls
    try{$s.MetadataRequest=$u.Engine.RequestInspector($Group,$s.Generation)}catch{$w.FindName('Status').Text=$_.Exception.Message}
}
function Apply-UiDetailsResult($Result) {
    $u=$script:reviewUi;$w=$u.DetailsWindow;if(-not $w -or -not $w.Tag){return $false};$s=$w.Tag
    if($Result.Kind -eq 'Inspector' -and $s.SourceRequest -and $Result.RequestId -eq $s.SourceRequest){
        if($Result.Generation -ne $s.Generation){return $false};$s.SourceRequest=''
        if(-not $Result.Success){$w.FindName('Summary').Text='Connected source summary unavailable: '+$Result.Error;return $true}
        $d=$Result.Inspector;if(-not $s.Data -or $d.GroupId -ne $s.GroupId -or $d.ContentId -ne $s.Data.ContentId){$w.FindName('Summary').Text='Item identity changed. Reload details before saving; your draft remains visible.';Update-UiDetailsControls;return $true}
        $s.Data.RootPath=$d.RootPath;$s.Data.LocationCount=$d.LocationCount;Update-UiDetailsSummary;Request-UiDetailsLocations -Restart;return $true
    }
    if($Result.Kind -eq 'Inspector'){
        if($Result.RequestId -ne $s.MetadataRequest -or $Result.Generation -ne $s.Generation){return $false}
        if(-not $Result.Success){$w.FindName('Summary').Text='Item details unavailable';$w.FindName('Status').Text=$Result.Error;Update-UiDetailsControls;return $true}
        $d=$Result.Inspector;if($d.GroupId -ne $s.GroupId){return $false};$s.Data=$d;$s.Loading=$true;$w.FindName('Reviewer').Text=$d.Reviewer;$w.FindName('Notes').Text=$d.Notes;$s.Loading=$false;$s.Dirty=$false
        Update-UiDetailsSummary
        $w.FindName('Status').Text=if($d.TextReadOnly){'Text exceeds the editor limits, contains unsupported characters, or is stored separately. A bounded display is shown; the complete original is preserved read-only.'}elseif($s.CommitMessage){$s.CommitMessage}else{'Edit reviewer and notes, then Save notes. The bucket stays unchanged.'}
        Update-UiDetailsControls;Request-UiDetailsLocations -Restart;return $true
    }
    if($Result.Kind -eq 'Locations'){
        if($Result.RequestId -ne $s.LocationRequest -or -not $s.Data){return $false};$s.LocationPending=$false
        if(-not $Result.Success){$w.FindName('LocationLabel').Text='Locations unavailable: '+$Result.Error;Update-UiDetailsControls;return $true}
        $p=$Result.Locations;if($p.GroupId -ne $s.GroupId -or $p.ContentId -ne $s.Data.ContentId){$w.FindName('LocationLabel').Text='Item identity changed; reload details.';Update-UiDetailsControls;return $false}
        $w.FindName('Locations').ItemsSource=$p.Rows;$start=$s.Shown+1;$s.Shown+=$p.Rows.Count;$s.Cursor=$p.NextAfter;$s.HasMore=$p.HasMore
        $w.FindName('LocationLabel').Text=if($p.Rows.Count){'Recorded locations {0:n0}-{1:n0} of {2:n0}. Historical means superseded; paths are not live availability checks.' -f $start,$s.Shown,$s.Data.LocationCount}else{'No source location is recorded. A retained original may still be available.'};Update-UiDetailsControls;return $true
    }
    if($Result.Kind -eq 'Notes'){
        if(-not $s.Saving -or $Result.RequestId -ne $s.SaveRequest){return $false};$s.Saving=$false
        if(-not $Result.Success){$w.FindName('Status').Text='Save failed; draft retained. '+$Result.Error;Update-UiDetailsControls;return $true}
        $s.Dirty=$false;$s.CommitMessage='Notes committed successfully.';Request-UiDetailsMetadata $s.GroupId;if(-not $u.PagePending){Request-UiPage};return $true
    };return $false
}
function Save-UiDetailsNotes {
    $u=$script:reviewUi;$w=$u.DetailsWindow;$s=$w.Tag;if($s.Saving -or -not $s.Data -or $s.Data.TextReadOnly -or -not $s.Dirty){return}
    $r=[MediaReviewer.NotesRequest]::new();$r.GroupId=$s.GroupId;$r.ContentId=$s.Data.ContentId;$r.ExpectedRevision=$s.Data.ReviewRevision;$r.Reviewer=$w.FindName('Reviewer').Text;$r.Notes=$w.FindName('Notes').Text
    if(-not $s.LastRequest -or $s.LastRequest.Reviewer -cne $r.Reviewer -or $s.LastRequest.Notes -cne $r.Notes){$s.OperationId=[Guid]::NewGuid().ToString('N')};$r.OperationId=$s.OperationId;$s.LastRequest=$r
    try{$s.SaveRequest=$u.Engine.RequestNotes($r);$s.Saving=$true;$w.FindName('Status').Text='Saving notes...';Update-UiDetailsControls}catch{$w.FindName('Status').Text='Save not queued; draft retained. '+$_.Exception.Message}
}
function Invalidate-UiDetailsGroup([long]$Group) {
    $u=$script:reviewUi;$w=$u.DetailsWindow;if($w -and $w.Tag -and $w.Tag.GroupId -eq $Group){$s=$w.Tag;$s.Generation=$u.DetailsGeneration.Advance();$s.Data=$null;$s.MetadataRequest='';$s.SourceRequest='';$s.LocationRequest='';$s.HasMore=$false;$w.FindName('Locations').ItemsSource=$null;$w.FindName('Summary').Text='This item identity changed. Reload details before saving.';$w.FindName('Status').Text='Any unsaved draft remains visible. Copy it if needed before Reload discards it.';Update-UiDetailsControls}
}
function Show-UiDetails($Card) {
    $u=$script:reviewUi;if($u.DetailsWindow -and ($u.DetailsWindow.Tag.Saving -or $u.DetailsWindow.Tag.Dirty)){$u.DetailsWindow.FindName('Status').Text='Save your notes, or use Reload to discard the draft, before opening another item.';$u.DetailsWindow.Activate() | Out-Null;return}
    if(-not $u.DetailsWindow){
        $markup=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Item details and notes" Width="900" Height="720" MinWidth="560" MinHeight="540" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI">
  <Grid Margin="16"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="150"/><RowDefinition Height="Auto"/><RowDefinition Height="110"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="64"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <WrapPanel><Button x:Name="Previous" Content="Previous item" Padding="10,5" Margin="0,0,6,6"/><Button x:Name="Next" Content="Next item" Padding="10,5" Margin="0,0,10,6"/><TextBlock x:Name="Position" VerticalAlignment="Center" TextWrapping="Wrap"/></WrapPanel>
    <TextBox Grid.Row="1" x:Name="Summary" IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" Padding="6"/>
    <WrapPanel Grid.Row="2" Margin="0,8"><TextBlock Text="Reviewer" VerticalAlignment="Center" Margin="0,0,8,0"/><TextBox x:Name="Reviewer" Width="200" MaxLength="128"/><Button x:Name="Save" Content="Save notes" Padding="12,5" Margin="10,0"/><Button x:Name="Reload" Content="Reload / discard edits" Padding="10,5"/></WrapPanel>
    <TextBox Grid.Row="3" x:Name="Notes" MaxLength="16384" AcceptsReturn="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" Padding="6" ToolTip="Current review notes; ordinary metadata is not encrypted"/>
    <DockPanel Grid.Row="4" Margin="0,8"><Button x:Name="MoreLocations" Content="Next 100 locations" DockPanel.Dock="Right" Padding="10,5" Margin="8,0,0,0"/><TextBlock x:Name="LocationLabel" TextWrapping="Wrap" VerticalAlignment="Center"/></DockPanel>
    <DataGrid Grid.Row="5" x:Name="Locations" IsReadOnly="True" AutoGenerateColumns="False" CanUserAddRows="False" CanUserDeleteRows="False" EnableRowVirtualization="True"><DataGrid.Columns><DataGridTextColumn Header="Recorded relative path" Binding="{Binding Path}" Width="*"/><DataGridTextColumn Header="Bytes" Binding="{Binding Size}" Width="100"/><DataGridCheckBoxColumn Header="Historical" Binding="{Binding Historical}" Width="75"/></DataGrid.Columns></DataGrid>
    <TextBlock Grid.Row="6" x:Name="Status" TextWrapping="Wrap" Margin="0,8"/>
    <Button Grid.Row="7" x:Name="Close" Content="Close" IsCancel="True" HorizontalAlignment="Center" Padding="24,6"/>
  </Grid>
</Window>
'@
        $w=[Windows.Markup.XamlReader]::Parse($markup);$w.Owner=$u.Window;$u.DetailsWindow=$w
        $w.FindName('Save').Add_Click({Save-UiDetailsNotes});$w.FindName('Reload').Add_Click({$w=$script:reviewUi.DetailsWindow;$w.Tag.CommitMessage='';Request-UiDetailsMetadata $w.Tag.GroupId});$w.FindName('MoreLocations').Add_Click({Request-UiDetailsLocations})
        $w.FindName('Previous').Add_Click({$w=$script:reviewUi.DetailsWindow;$card=Get-UiPageNeighbor $w.Tag.GroupId -1;if($card){Show-UiDetails $card}});$w.FindName('Next').Add_Click({$w=$script:reviewUi.DetailsWindow;$card=Get-UiPageNeighbor $w.Tag.GroupId 1;if($card){Show-UiDetails $card}})
        foreach($name in @('Reviewer','Notes')){$w.FindName($name).Add_TextChanged({$w=$script:reviewUi.DetailsWindow;if($w -and $w.Tag -and -not $w.Tag.Loading){$w.Tag.Dirty=$true;Update-UiDetailsControls}})}
        $w.FindName('Close').Add_Click({$script:reviewUi.DetailsWindow.Close()})
        $w.Add_Closing({param($sender,$event) if($sender.Tag.Saving){$event.Cancel=$true;$sender.FindName('Status').Text='Waiting for the notes commit; close after its outcome is known.'}elseif($sender.Tag.Dirty -and [Windows.MessageBox]::Show($sender,'Discard the unsaved notes?','Unsaved notes','YesNo','Question') -ne 'Yes'){$event.Cancel=$true}})
        $w.Add_Closed({param($sender,$event) $u=$script:reviewUi;$sender.Tag=$null;$sender.FindName('Notes').Clear();$sender.FindName('Reviewer').Clear();$sender.FindName('Summary').Clear();$sender.FindName('Locations').ItemsSource=$null;if($u.DetailsWindow -eq $sender){$u.DetailsWindow=$null;[void]$u.DetailsGeneration.Advance()}})
        $w.Tag=[pscustomobject]@{GroupId=0L;Generation=0L;Data=$null;MetadataRequest='';SourceRequest='';LocationRequest='';LocationPending=$false;Cursor='';HasMore=$false;Shown=0L;Loading=$true;Saving=$false;Dirty=$false;SaveRequest='';OperationId='';LastRequest=$null;CommitMessage=''}
    }
    $u.DetailsWindow.Tag.CommitMessage='';Request-UiDetailsMetadata $Card.Record.GroupId;$u.DetailsWindow.Show();$u.DetailsWindow.Activate() | Out-Null
}

function Update-UiPreviewRecoveryControls {
    $u=$script:reviewUi;if(-not $u -or -not $u.Controls.RetryPreviewsButton){return};$ready=$u.Engine -and $u.Engine.Ready -and -not $u.Opening -and -not $u.Closing
    $selected=@($u.Cards | Where-Object {$_.IsSelected -and -not $_.IsPending});$u.Controls.RetryPreviewsButton.IsEnabled=$ready -and -not $u.MaintenancePending -and $selected.Count -gt 0 -and $selected.Count -le 200 -and $u.Bucket -ne 'EVIDENCE';$u.Controls.PreviewTasksButton.IsEnabled=$ready
    $w=$u.RecoveryWindow;if($w -and $w.Tag){$eligible=$ready -and -not $u.MaintenancePending -and $w.Tag.Batch -and $w.Tag.Batch.State -in @('queued','interrupted');$w.FindName('Resume').IsEnabled=$eligible;$w.FindName('Discard').IsEnabled=$eligible;$w.FindName('Refresh').IsEnabled=$ready}
}
function Start-UiPreviewRetry {
    $u=$script:reviewUi;if($u.MaintenancePending){return};$cards=@($u.Cards | Where-Object {$_.IsSelected -and -not $_.IsPending});if(-not $cards.Count){return}
    try{$id=$u.Engine.RequestPreviewRetry([long[]]@($cards | ForEach-Object {$_.Record.GroupId}));$u.BackgroundOperationId=$id;$u.MaintenancePending=$true;if($u.RecoveryWindow){$u.RecoveryWindow.Tag.BatchId=$id};Set-UiMessage ('Queued preview retry for '+$cards.Count+' selected item(s). Saved previews remain available.');Update-UiControls}catch{Set-UiMessage ('Preview work was not queued: '+$_.Exception.Message)}
}
function Request-UiPreviewHistory {
    $u=$script:reviewUi;$w=$u.RecoveryWindow;if(-not $w){return};$w.FindName('Status').Text='Loading saved preview tasks...';try{$w.Tag.HistoryRequest=$u.Engine.RequestPreviewRetryHistory()}catch{$w.FindName('Status').Text=$_.Exception.Message}
}
function Request-UiPreviewStatus {
    $u=$script:reviewUi;$w=$u.RecoveryWindow;if(-not $w -or -not $w.FindName('Batches').SelectedItem){return};$w.Tag.BatchId=$w.FindName('Batches').SelectedItem.Id;$w.Tag.Batch=$null;$w.FindName('Items').ItemsSource=$null;$w.FindName('Status').Text='Loading recorded outcomes...';Update-UiPreviewRecoveryControls
    try{$w.Tag.StatusRequest=$u.Engine.RequestPreviewRetryStatus($w.Tag.BatchId)}catch{$w.FindName('Status').Text=$_.Exception.Message}
}
function Apply-UiPreviewRecoveryResult($Result) {
    $u=$script:reviewUi
    if($Result.Kind -eq 'PreviewRetry'){
        if($Result.RequestId -ne $u.BackgroundOperationId){return $false};$u.BackgroundOperationId='';$u.MaintenancePending=$false;Set-UiMessage $(if($Result.Success){$Result.Value}else{'Preview task stopped: '+$Result.Error+' Open Preview tasks to resume unfinished work.'});if($u.RecoveryWindow){Request-UiPreviewHistory};if(-not $u.PagePending){Request-UiPage};Update-UiControls;return $true
    }
    $w=$u.RecoveryWindow;if(-not $w -or -not $w.Tag){return $false}
    if($Result.Kind -eq 'PreviewRetryHistory'){
        if($Result.RequestId -ne $w.Tag.HistoryRequest){return $false};if(-not $Result.Success){$w.FindName('Status').Text=$Result.Error;return $true}
        $s=$w.Tag;$s.Loading=$true;$w.FindName('Batches').ItemsSource=$Result.PreviewRetries;$selected=$Result.PreviewRetries | Where-Object {$_.Id -eq $s.BatchId} | Select-Object -First 1;if(-not $selected){$selected=$Result.PreviewRetries | Select-Object -First 1};$w.FindName('Batches').SelectedItem=$selected;$s.Loading=$false
        if($selected){Request-UiPreviewStatus}else{$s.Batch=$null;$s.BatchId='';$w.FindName('Items').ItemsSource=$null;$w.FindName('Status').Text='No saved preview tasks. Select gallery cards and choose Retry previews.';Update-UiPreviewRecoveryControls};return $true
    }
    if($Result.Kind -eq 'PreviewRetryStatus'){
        if($Result.RequestId -ne $w.Tag.StatusRequest){return $false};if(-not $Result.Success){$w.FindName('Status').Text=$Result.Error;return $true};if($Result.PreviewRetry.Id -ne $w.Tag.BatchId){return $false}
        $w.Tag.Batch=$Result.PreviewRetry;$w.FindName('Items').ItemsSource=$Result.PreviewRetry.Items;$w.FindName('Status').Text=('{0}: {1:n0} saved, {2:n0} failed, {3:n0} selected. Resume processes unfinished rows only. Use Refresh for current outcomes; Cancel task is on the main window.' -f $Result.PreviewRetry.State,$Result.PreviewRetry.Saved,$Result.PreviewRetry.Failed,$Result.PreviewRetry.Total);Update-UiPreviewRecoveryControls;return $true
    };return $false
}
function Show-UiPreviewRecovery {
    $u=$script:reviewUi;if(-not $u.RecoveryWindow){
        $markup=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Preview recovery" Width="900" Height="640" MinWidth="560" MinHeight="400" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI">
  <Grid Margin="16"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="75"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock Text="Retry up to 200 selected gallery items. Good saved previews, fingerprints, review decisions and originals stay intact. Resume unfinished tasks after reopening. Failed sources require a fresh selected retry; changed contents need a rescan." TextWrapping="Wrap" Margin="0,0,0,10"/>
    <WrapPanel Grid.Row="1" Margin="0,0,0,10"><ComboBox x:Name="Batches" Width="460" DisplayMemberPath="Label" Margin="0,0,8,6"/><Button x:Name="Refresh" Content="Refresh" Padding="12,5" Margin="0,0,8,6"/><Button x:Name="Resume" Content="Resume unfinished" Padding="12,5" Margin="0,0,8,6"/><Button x:Name="Discard" Content="Discard pending" Padding="12,5" Margin="0,0,0,6"/></WrapPanel>
    <DataGrid Grid.Row="2" x:Name="Items" IsReadOnly="True" AutoGenerateColumns="False" CanUserAddRows="False" CanUserDeleteRows="False"><DataGrid.Columns><DataGridTextColumn Header="Item" Binding="{Binding GroupId}" Width="80"/><DataGridTextColumn Header="Outcome" Binding="{Binding State}" Width="100"/><DataGridTextColumn Header="Details (affected paths are also in Log)" Binding="{Binding Error}" Width="*"/></DataGrid.Columns></DataGrid>
    <TextBlock Grid.Row="3" x:Name="Status" TextWrapping="Wrap" Margin="0,8"/>
    <Button Grid.Row="4" x:Name="Close" Content="Close" HorizontalAlignment="Center" Padding="24,6" IsCancel="True"/>
  </Grid>
</Window>
'@
        $w=[Windows.Markup.XamlReader]::Parse($markup);$w.Owner=$u.Window;$w.Tag=[pscustomobject]@{HistoryRequest='';StatusRequest='';BatchId='';Batch=$null;Loading=$false};$u.RecoveryWindow=$w
        $w.FindName('Batches').Add_SelectionChanged({$w=$script:reviewUi.RecoveryWindow;if($w -and -not $w.Tag.Loading){Request-UiPreviewStatus}});$w.FindName('Refresh').Add_Click({Request-UiPreviewHistory})
        $w.FindName('Resume').Add_Click({$u=$script:reviewUi;try{$u.BackgroundOperationId=$u.Engine.RequestResumePreviewRetry($u.RecoveryWindow.Tag.BatchId);$u.MaintenancePending=$true;Set-UiMessage 'Resuming unfinished preview work...';Update-UiControls}catch{$u.RecoveryWindow.FindName('Status').Text=$_.Exception.Message}})
        $w.FindName('Discard').Add_Click({$u=$script:reviewUi;try{$u.BackgroundOperationId=$u.Engine.RequestDiscardPreviewRetry($u.RecoveryWindow.Tag.BatchId);$u.MaintenancePending=$true;Set-UiMessage 'Discarding pending preview work; saved results remain.';Update-UiControls}catch{$u.RecoveryWindow.FindName('Status').Text=$_.Exception.Message}})
        $w.FindName('Close').Add_Click({$script:reviewUi.RecoveryWindow.Close()});$w.Add_Closed({param($sender,$event) $sender.FindName('Batches').ItemsSource=$null;$sender.FindName('Items').ItemsSource=$null;$sender.Tag=$null;if($script:reviewUi.RecoveryWindow -eq $sender){$script:reviewUi.RecoveryWindow=$null}})
    };$u.RecoveryWindow.Show();$u.RecoveryWindow.Activate() | Out-Null;Request-UiPreviewHistory;Update-UiPreviewRecoveryControls
}
function Add-UiPreviewRecoveryControls($Window) {
    $u=$script:reviewUi;$u | Add-Member -NotePropertyName RecoveryWindow -NotePropertyValue $null
    foreach($name in @('PreviewTasksButton','RetryPreviewsButton')){$u.Controls[$name]=$Window.FindName($name)};$u.Controls.PreviewTasksButton.Add_Click({Show-UiPreviewRecovery});$u.Controls.RetryPreviewsButton.Add_Click({Start-UiPreviewRetry});Update-UiPreviewRecoveryControls
    $u | Add-Member -NotePropertyName SourcesWindow -NotePropertyValue $null;$u | Add-Member -NotePropertyName SourceApplyPath -NotePropertyValue '';$u | Add-Member -NotePropertyName SourceRefreshRequired -NotePropertyValue $false
    $item=[Windows.Controls.MenuItem]::new();$item.Header='Sources / reconnect...';$item.Add_Click({Show-UiSources});$u.Controls.MaintenanceButton.ContextMenu.Items.Add($item) | Out-Null
}
function Update-UiSourceControls {
    $u=$script:reviewUi;$w=$u.SourcesWindow;if(-not $w -or -not $w.Tag){return};$s=$w.Tag;$ready=$u.Engine -and $u.Engine.Ready -and -not $u.Opening -and -not $u.Closing;$idle=$ready -and -not $u.MaintenancePending -and -not $u.Engine.Status.RunningScan -and -not $s.Loading;$check=$s.Check
    $w.FindName('Check').IsEnabled=$idle -and $s.Root -and (-not $check -or $check.State -in @('applied','superseded'))
    $w.FindName('Resume').IsEnabled=$idle -and $check -and $check.State -eq 'interrupted';$w.FindName('Discard').IsEnabled=$idle -and $check -and $check.State -in @('interrupted','ready','discarding')
    $w.FindName('Apply').IsEnabled=$idle -and $check -and $check.State -eq 'ready' -and $check.Failed -eq 0 -and ($check.Full+$check.Candidates) -gt 0 -and (($check.Candidates+$check.Missing) -eq 0 -or $w.FindName('Accept').IsChecked)
    $w.FindName('NewPath').IsEnabled=$idle;$w.FindName('Browse').IsEnabled=$idle;$w.FindName('Roots').IsEnabled=$ready -and -not $s.Loading;$w.FindName('Next').IsEnabled=$ready -and -not $s.Loading -and $s.HasMore
}
function Request-UiSourceRoots([switch]$First,[switch]$Next) {
    $u=$script:reviewUi;$w=$u.SourcesWindow;if(-not $w){return};$s=$w.Tag;if($First){$s.After=''};if($Next){$s.After=$s.Next};if($s.Root){$s.Hint=$s.Root.Id};$s.Root=$null;$s.Check=$null;$s.StatusRequest='';$s.Loading=$true;$w.FindName('Files').ItemsSource=$null;$w.FindName('Status').Text='Loading recorded sources...';Update-UiSourceControls
    try{$s.RootsRequest=$u.Engine.RequestSourceRoots($s.After)}catch{$s.Loading=$false;$w.FindName('Status').Text=$_.Exception.Message;Update-UiSourceControls}
}
function Select-UiSourceRoot {
    $u=$script:reviewUi;$w=$u.SourcesWindow;if(-not $w -or $w.Tag.Loading){return};$s=$w.Tag;$s.Root=$w.FindName('Roots').SelectedItem;$s.Check=$null;$s.StatusRequest='';$w.FindName('Files').ItemsSource=$null;$w.FindName('Accept').IsChecked=$false
    if($s.Root){$w.FindName('Current').Text='Current: '+$s.Root.Path+"`nRecorded: "+$s.Root.RecordedPath;$w.FindName('NewPath').Text=$s.Root.Path
        if($s.Root.ConnectionId){try{$s.StatusRequest=$u.Engine.RequestSourceConnectionStatus($s.Root.ConnectionId);$s.Loading=$true;$w.FindName('Status').Text='Loading the recorded source check...'}catch{$w.FindName('Status').Text=$_.Exception.Message}}else{$w.FindName('Status').Text='Choose the replacement root, then Check folder. Nothing changes until you apply a completed check.'}
    }else{$w.FindName('Current').Text='No sources on this page.';$w.FindName('Status').Text='Scan or open a database with recorded locations first.'};Update-UiSourceControls
}
function Start-UiSourceOperation([string]$Action) {
    $u=$script:reviewUi;$w=$u.SourcesWindow;if(-not $w -or $u.MaintenancePending){return};$s=$w.Tag
    try{$id=switch($Action){'Check'{$u.Engine.RequestRootRemap($s.Root.Id,$w.FindName('NewPath').Text,$false)}'Resume'{$u.Engine.RequestResumeSourceConnection($s.Check.Id)}'Apply'{$u.SourceApplyPath=$s.Check.Path;$u.Engine.RequestApplySourceConnection($s.Check.Id,[bool]$w.FindName('Accept').IsChecked)}'Discard'{$u.Engine.RequestDiscardSourceConnection($s.Check.Id)}}
        $u.BackgroundOperationId=$id;$u.MaintenancePending=$true;Set-UiMessage ('Source '+$Action.ToLowerInvariant()+' queued. Cached previews remain available.');$w.FindName('Status').Text='Working in the background. Use Cancel task on the main window to stop unfinished work.';Update-UiControls
    }catch{$w.FindName('Status').Text=$_.Exception.Message}
}
function Apply-UiSourceResult($Result) {
    $u=$script:reviewUi
    if($Result.Kind -in @('SourceCheck','SourceApply','SourceDiscard')){
        if($Result.RequestId -ne $u.BackgroundOperationId){return $false};$u.BackgroundOperationId='';$u.MaintenancePending=$false;Set-UiMessage $(if($Result.Success){$Result.Value}else{'Source task stopped: '+$Result.Error+' Refresh Sources to inspect or resume its saved work.'})
        if($Result.Kind -eq 'SourceApply'){if($u.Inspector){$u.Inspector.Close()};if($Result.Success){$u.Controls.SourceBox.Text=$u.SourceApplyPath};[void]$u.InspectView.Advance();$u.Loader.CancelInspect($u.InspectView.Current);$u.SourceRefreshRequired=$true;Refresh-UiDetailsSource;[void]$u.View.Advance();$u.PageRequest='';$u.PagePending=$false;Request-UiPage}
        if($u.SourcesWindow){Request-UiSourceRoots};Update-UiControls;return $true
    }
    $w=$u.SourcesWindow;if(-not $w -or -not $w.Tag){return $false};$s=$w.Tag
    if($Result.Kind -eq 'SourceRoots'){
        if($Result.RequestId -ne $s.RootsRequest){return $false};if(-not $Result.Success){$s.Loading=$false;$w.FindName('Status').Text=$Result.Error;Update-UiSourceControls;return $true};$s.Next=$Result.SourceRoots.Next;$s.HasMore=$Result.SourceRoots.HasMore;$w.FindName('Roots').ItemsSource=$Result.SourceRoots.Rows;$chosen=$Result.SourceRoots.Rows | Where-Object {$_.Id -eq $s.Hint} | Select-Object -First 1;if(-not $chosen){$chosen=$Result.SourceRoots.Rows | Select-Object -First 1};$w.FindName('Roots').SelectedItem=$chosen;$s.Loading=$false;Select-UiSourceRoot;return $true
    }
    if($Result.Kind -eq 'SourceConnectionStatus'){
        if($Result.RequestId -ne $s.StatusRequest){return $false};$s.Loading=$false;if(-not $Result.Success){$w.FindName('Status').Text=$Result.Error;Update-UiSourceControls;return $true};if(-not $s.Root -or $Result.SourceConnection.RootId -ne $s.Root.Id){return $false};$s.Check=$Result.SourceConnection;$w.FindName('Files').ItemsSource=$s.Check.Rows;$w.FindName('Status').Text=('{0}: {1:n0} full matches, {2:n0} quick candidates, {3:n0} missing, {4:n0} failed. {5:n0} recorded files. Only the latest 20 checked paths appear below; Log includes failures and retries. A connection requires at least one match and no failures.' -f $s.Check.State,$s.Check.Full,$s.Check.Candidates,$s.Check.Missing,$s.Check.Failed,$s.Check.Total);Update-UiSourceControls;return $true
    };return $false
}
function Show-UiSources {
    $u=$script:reviewUi;if(-not $u.SourcesWindow){
        $markup=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Sources / reconnect" Width="940" Height="700" MinWidth="600" MinHeight="560" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI">
  <Grid Margin="16"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="95"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock Text="Check a replacement folder before reconnecting saved media. Recorded identities, reviews, Evidence and completed scan users stay intact. Checks can take time on large collections; cancel and resume unfinished work. Pause scanning first." TextWrapping="Wrap" Margin="0,0,0,10"/>
    <Grid Grid.Row="1"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><ComboBox x:Name="Roots" DisplayMemberPath="Label" MinHeight="30"/><Button Grid.Column="1" x:Name="Refresh" Content="Refresh" Padding="10,5" Margin="6,0,0,0"/><Button Grid.Column="2" x:Name="First" Content="First roots" Padding="10,5" Margin="6,0,0,0"/><Button Grid.Column="3" x:Name="Next" Content="Next roots" Padding="10,5" Margin="6,0,0,0"/></Grid>
    <TextBlock Grid.Row="2" x:Name="Current" TextWrapping="Wrap" MaxHeight="68" Margin="0,8"/>
    <Grid Grid.Row="3"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="NewPath" MinHeight="30" Padding="6" ToolTip="Replacement root: local folder, mapped drive or UNC share"/><Button Grid.Column="1" x:Name="Browse" Content="Browse..." Padding="10,5" Margin="6,0,0,0"/></Grid>
    <StackPanel Grid.Row="4" Margin="0,8"><WrapPanel><Button x:Name="Check" Content="Check folder" Padding="12,5" Margin="0,0,8,5"/><Button x:Name="Resume" Content="Resume check" Padding="12,5" Margin="0,0,8,5"/><Button x:Name="Discard" Content="Discard check" Padding="12,5" Margin="0,0,8,5"/><Button x:Name="Apply" Content="Apply connection" Padding="12,5" Margin="0,0,8,5"/></WrapPanel><CheckBox x:Name="Accept"><TextBlock Text="I accept quick candidate matches and missing files. A quick match does not prove identical full contents." TextWrapping="Wrap"/></CheckBox></StackPanel>
    <DataGrid Grid.Row="5" x:Name="Files" AutoGenerateColumns="False" IsReadOnly="True" CanUserAddRows="False" CanUserDeleteRows="False"><DataGrid.Columns><DataGridTextColumn Header="Recorded path (latest 20)" Binding="{Binding Path}" Width="2*"/><DataGridTextColumn Header="Outcome" Binding="{Binding State}" Width="100"/><DataGridTextColumn Header="Details" Binding="{Binding Error}" Width="3*"/></DataGrid.Columns></DataGrid>
    <TextBlock Grid.Row="6" x:Name="Status" TextWrapping="Wrap" Margin="0,8"/><Button Grid.Row="7" x:Name="Close" Content="Close" Padding="24,6" HorizontalAlignment="Center" IsCancel="True"/>
  </Grid>
</Window>
'@
        $w=[Windows.Markup.XamlReader]::Parse($markup);$w.Owner=$u.Window;$w.Tag=[pscustomobject]@{Root=$null;Check=$null;After='';Next='';Hint='';HasMore=$false;RootsRequest='';StatusRequest='';Loading=$false};$u.SourcesWindow=$w
        $w.FindName('Roots').Add_SelectionChanged({Select-UiSourceRoot});$w.FindName('Refresh').Add_Click({Request-UiSourceRoots});$w.FindName('First').Add_Click({Request-UiSourceRoots -First});$w.FindName('Next').Add_Click({Request-UiSourceRoots -Next});$w.FindName('Accept').Add_Checked({Update-UiSourceControls});$w.FindName('Accept').Add_Unchecked({Update-UiSourceControls})
        foreach($name in @('Check','Resume','Apply','Discard')){$w.FindName($name).Tag=$name;$w.FindName($name).Add_Click({param($sender,$event) Start-UiSourceOperation $sender.Tag})}
        $w.FindName('Browse').Add_Click({$picker=[Windows.Forms.FolderBrowserDialog]::new();$picker.Description='Choose the replacement root or paste a UNC path.';try{if($picker.ShowDialog() -eq [Windows.Forms.DialogResult]::OK){$script:reviewUi.SourcesWindow.FindName('NewPath').Text=$picker.SelectedPath}}finally{$picker.Dispose()}})
        $w.FindName('Close').Add_Click({$script:reviewUi.SourcesWindow.Close()});$w.Add_Closed({param($sender,$event) $sender.FindName('Roots').ItemsSource=$null;$sender.FindName('Files').ItemsSource=$null;$sender.Tag=$null;if($script:reviewUi.SourcesWindow -eq $sender){$script:reviewUi.SourcesWindow=$null}})
    };$u.SourcesWindow.Show();$u.SourcesWindow.Activate() | Out-Null;Request-UiSourceRoots
}

function Initialize-UiPreferences {
    $u=$script:reviewUi
    $state=[pscustomobject]@{Loaded=$false;ReadOnly=$false;LoadFailed=$false;LoadRequest='';SaveRequest='';Saved='';Observed='';Current=$null;InFlight=$null;OperationId='';AttemptSignature='';Due=[DateTime]::UtcNow;ErrorSignature='';LastValidAge=0;Exit=$null}
    if($u.PSObject.Properties['Preferences']){$u.Preferences=$state}else{$u | Add-Member -NotePropertyName Preferences -NotePropertyValue $state}
}
function Get-UiPreferences {
    $u=$script:reviewUi;$p=[MediaReviewer.ReviewPreferences]::new()
    $p.PageSize=[int]$u.Controls.PageSizeBox.SelectedItem;$p.Fit=[string]$u.Controls.FitBox.SelectedItem.Tag;$p.WorkerCount=[int]$u.Controls.WorkerBox.SelectedItem
    $p.Mode=@('Quick','Deep','Custom')[$u.Controls.ModeBox.SelectedIndex];$p.Families=[string[]]@([MediaReviewer.Formats]::Families | Where-Object {$u.FormatChoices[$_.Key].IsChecked} | ForEach-Object {$_.Key})
    $age=0;if([int]::TryParse($u.Controls.AgeBox.Text,[ref]$age) -and $age -ge 0 -and $age -le 9999){$u.Preferences.LastValidAge=$age};$p.ModifiedAgeYears=$u.Preferences.LastValidAge
    $p.IncludeApplicationData=[bool]$u.Controls.AppDataOption.IsChecked;$p.IncludeRootFiles=[bool]$u.Controls.RootFilesOption.IsChecked;$p.Reviewer=$u.Controls.ReviewerBox.Text
    return $p
}
function Restore-UiPreferences([MediaReviewer.ReviewPreferences]$Preferences) {
    $u=$script:reviewUi;$p=$Preferences;$u.SuppressEvents=$true
    try{
        $u.Controls.PageSizeBox.SelectedItem=$p.PageSize;$u.PageSize=$p.PageSize;$u.Controls.FitBox.SelectedIndex=if($p.Fit -eq 'UniformToFill'){1}else{0};$u.Controls.WorkerBox.SelectedItem=$p.WorkerCount
        $u.Controls.ModeBox.SelectedIndex=[Array]::IndexOf(@('Quick','Deep','Custom'),$p.Mode)
        foreach($family in [MediaReviewer.Formats]::Families){$u.FormatChoices[$family.Key].IsChecked=$family.Key -in $p.Families};Update-UiFormatSummary
        $u.Controls.AppDataOption.IsChecked=$p.IncludeApplicationData;$u.Controls.RootFilesOption.IsChecked=$p.IncludeRootFiles;$u.Controls.AgeBox.Text=[string]$p.ModifiedAgeYears;$u.Preferences.LastValidAge=$p.ModifiedAgeYears;$u.Controls.ReviewerBox.Text=$p.Reviewer
        $u.Page=1;$u.Bucket='TO_REVIEW';$u.Controls.NotesBox.Clear();$u.Controls.SearchBox.Clear();$u.Controls.FolderBox.Clear();$u.Controls.TypeBox.SelectedIndex=0;$u.Controls.SortBox.SelectedIndex=0;$u.Controls.PageBox.Text='1'
    }finally{$u.SuppressEvents=$false}
    $s=$u.Preferences;$s.Loaded=$true;$s.ReadOnly=$p.ReadOnly;$s.Current=Get-UiPreferences;$s.Saved=$s.Current.Signature;$s.Observed=$s.Saved
    $u.Controls.PreferencesText.Text=if($p.Warning){$p.Warning}else{'Preferences loaded for this database.'}
    $u.Controls.RetryPreferencesButton.Visibility='Hidden';$u.Initialized=$true;$u.Opening=$false;$u.Controls.DatabaseLabel.Text=$u.Engine.DatabasePath;Request-UiPage -Reset
}
function Invoke-UiPreferencesTick([switch]$Flush) {
    $u=$script:reviewUi;$s=$u.Preferences;if(-not $s -or -not $s.Loaded -or $s.ReadOnly -or -not $u.Engine -or -not $u.Engine.Ready -or $u.Closing -or $u.Opening){return}
    try{$current=Get-UiPreferences;$signature=$current.Signature}catch{$u.Controls.PreferencesText.Text='Preferences not saved: '+$_.Exception.Message;return}
    if($signature -cne $s.Observed){$s.Observed=$signature;$s.Current=$current;$s.Due=[DateTime]::UtcNow.AddMilliseconds(500);$s.ErrorSignature='';$u.Controls.RetryPreferencesButton.Visibility='Hidden';$u.Controls.PreferencesText.Text='Preferences pending...'}
    if($signature -ceq $s.Saved -and -not $s.SaveRequest){if($u.Controls.PreferencesText.Text -eq 'Preferences pending...'){$u.Controls.PreferencesText.Text='Preferences unchanged.'};return}
    if(-not $s.SaveRequest -and $s.ErrorSignature -cne $signature -and ($Flush -or [DateTime]::UtcNow -ge $s.Due)){
        if($s.AttemptSignature -cne $signature){$s.OperationId=[Guid]::NewGuid().ToString('N');$s.AttemptSignature=$signature}
        try{$s.SaveRequest=$u.Engine.RequestSavePreferences($s.Current,$s.OperationId);$s.InFlight=$signature;$u.Controls.PreferencesText.Text='Preferences saving...'}
        catch{$s.ErrorSignature=$signature;$s.Exit=$null;$u.Controls.PreferencesText.Text='Preferences not queued: '+$_.Exception.Message;$u.Controls.RetryPreferencesButton.Visibility='Visible'}
    }
}
function Test-UiPreferencesExit($Next) {
    $u=$script:reviewUi;$s=$u.Preferences
    if(-not $s.Loaded -or $s.ReadOnly -or -not $u.Engine.Ready -or $u.Engine.Faulted){return $true}
    Invoke-UiPreferencesTick -Flush
    if($s.SaveRequest -or $s.Observed -cne $s.Saved){if(-not $s.ErrorSignature){$s.Exit=$Next};return $false}
    return $true
}
function Complete-UiPreferencesExit {
    $u=$script:reviewUi;$s=$u.Preferences;if(-not $s.Exit){return};Invoke-UiPreferencesTick -Flush
    if($u.Engine.Faulted -or (-not $s.SaveRequest -and $s.Observed -ceq $s.Saved)){$next=$s.Exit;$s.Exit=$null;if($next.Kind -eq 'Close'){$u.Window.Close()}else{Open-UiDatabase $next.Path $next.Create $next.ImportSource}}
}
function Apply-UiPreferencesResult($Result) {
    $u=$script:reviewUi;$s=$u.Preferences
    if($Result.Kind -eq 'Preferences'){
        if(-not $s.LoadRequest -or $Result.RequestId -ne $s.LoadRequest){return $false};$s.LoadRequest=''
        if($Result.Success){Restore-UiPreferences $Result.Preferences}else{$s.LoadFailed=$true;$u.Controls.PreferencesText.Text='Preferences unavailable: '+$Result.Error;$u.Controls.RetryPreferencesButton.Visibility='Visible'};return $true
    }
    if($Result.Kind -eq 'PreferencesSaved'){
        if(-not $s.SaveRequest -or $Result.RequestId -ne $s.SaveRequest){return $false};$s.SaveRequest=''
        if($Result.Success){$s.Saved=$s.InFlight;$u.Controls.PreferencesText.Text=if($s.Saved -ceq $s.Observed){'Preferences committed.'}else{'Preferences pending...'}}
        else{$s.ErrorSignature=$s.InFlight;$s.Exit=$null;$u.Controls.PreferencesText.Text='Preferences not saved: '+$Result.Error;$u.Controls.RetryPreferencesButton.Visibility='Visible'};return $true
    };return $false
}
function Add-UiPreferencesControls {
    $u=$script:reviewUi;foreach($name in @('PreferencesText','RetryPreferencesButton')){$u.Controls[$name]=$u.Window.FindName($name)};Initialize-UiPreferences
    $u.Controls.RetryPreferencesButton.Add_Click({$u=$script:reviewUi;$s=$u.Preferences;if(-not $s.Loaded){try{$s.LoadRequest=$u.Engine.RequestPreferences();$u.Controls.PreferencesText.Text='Loading saved preferences...';$u.Controls.RetryPreferencesButton.Visibility='Hidden'}catch{$u.Controls.PreferencesText.Text=$_.Exception.Message}}else{$s.ErrorSignature='';Invoke-UiPreferencesTick -Flush}})
}

function Update-UiReportControls {
    $u=$script:reviewUi;$w=$u.ReportWindow;if(-not $w){return};$ready=$u.Engine -and $u.Engine.Ready -and -not $u.Opening -and -not $u.Closing -and -not $u.MaintenancePending -and -not $u.Engine.Status.RunningScan -and -not $u.Pending.Count -and -not ($u.DetailsWindow -and $u.DetailsWindow.Tag.Saving)
    $w.FindName('Export').IsEnabled=$ready;$w.FindName('Unlock').IsEnabled=$ready -and -not $u.Engine.VaultUnlocked;$w.FindName('Unlock').Content=if($u.Engine.VaultUnlocked){'Originals unlocked'}else{'Unlock originals...'}
}
function Start-UiReport {
    $u=$script:reviewUi;$w=$u.ReportWindow;if(-not $w -or $u.MaintenancePending){return}
    try{if($u.Pending.Count -or ($u.DetailsWindow -and $u.DetailsWindow.Tag.Saving)){throw 'Wait for the pending review to commit before exporting.'};$options=[MediaReviewer.ReportOptions]::new();$options.Destination=$w.FindName('Destination').Text;$options.Format=if($w.FindName('Format').SelectedIndex -eq 1){'HtmlDirectory'}else{'Csv'};$options.IncludeEvidence=[bool]$w.FindName('IncludeEvidence').IsChecked;$options.IncludeSavedPreviews=[bool]$w.FindName('Previews').IsChecked;$options.SpreadsheetSafeText=[bool]$w.FindName('SafeText').IsChecked
        $u.BackgroundOperationId=$u.Engine.RequestReport($options);$u.MaintenancePending=$true;Set-UiMessage 'Report queued. Review changes are paused; cached inspection remains available. Use Cancel task to stop.';$w.Close();Update-UiControls
    }catch{$w.FindName('Status').Text=$_.Exception.Message;Update-UiReportControls}
}
